func TestBrokerRequests(t *testing.T) {
	s := NewServer(1)
	s.connLimiter = make(chan struct{}, 10)
	request := func(method, path, body string) (int, string) {
		t.Helper()
		raw := fmt.Sprintf("%s %s HTTP/1.1\r\nHost: localhost\r\nContent-Length: %d\r\n\r\n%s", method, path, len(body), body)
		status, _, response := exchangeWithServer(t, s, raw)
		return status, response
	}
	for _, route := range []string{"subscribe", "unsubscribe", "publish", "events"} {
		method, wrong := "POST", "GET"
		if route == "events" {
			method, wrong = "GET", "POST"
		}
		if status, _ := request(method, "/"+route, ""); status != 400 {
			t.Fatalf("%s missing topic: status=%d", route, status)
		}
		if status, _ := request(wrong, "/"+route+"?topic=news", ""); status != 501 {
			t.Fatalf("%s wrong method: status=%d", route, status)
		}
	}
	for _, route := range []string{"unsubscribe", "events"} {
		method := "POST"
		if route == "events" {
			method = "GET"
		}
		for _, id := range []string{"", "abc", "-1", "999999"} {
			if status, _ := request(method, "/"+route+"?topic=news&id="+id, ""); status != 400 {
				t.Fatalf("%s invalid id %q: status=%d", route, id, status)
			}
		}
	}
	status, body := request("POST", "/subscribe?topic=news", "")
	var subscription struct{ ID int }
	if status != 200 || json.Unmarshal([]byte(body), &subscription) != nil {
		t.Fatalf("subscribe status=%d body=%q", status, body)
	}
	path := fmt.Sprintf("?topic=news&id=%d", subscription.ID)
	if status, _ := request("GET", fmt.Sprintf("/events?topic=other&id=%d", subscription.ID), ""); status != 400 {
		t.Fatalf("wrong topic: status=%d", status)
	}
	data := "\x00\xffbinary\x01"
	if status, _ := request("POST", "/publish?topic=news", data); status != 200 {
		t.Fatalf("publish status=%d", status)
	}
	status, body = request("GET", "/events"+path, "")
	var msg Message
	if status != 200 || json.Unmarshal([]byte(body), &msg) != nil || string(msg.Data) != data {
		t.Fatalf("event status=%d body=%q", status, body)
	}
	if status, _ := request("POST", "/unsubscribe"+path, ""); status != 200 {
		t.Fatalf("unsubscribe status=%d", status)
	}
	if status, _ := request("POST", "/unsubscribe"+path, ""); status != 400 {
		t.Fatalf("repeat unsubscribe status=%d", status)
	}
	if status, _ := request("GET", "/events"+path, ""); status != 400 {
		t.Fatalf("cancelled events status=%d", status)
	}
}

func TestEventWait(t *testing.T) {
	s := NewServer(1)
	s.connLimiter = make(chan struct{}, 1)
	s.connLimiter <- struct{}{}
	events := make(chan Message)
	if _, status := s.waitForEvent(events, time.Millisecond); status != http.StatusNoContent {
		t.Fatalf("timeout status=%d", status)
	}
	if len(s.connLimiter) != 1 {
		t.Fatal("worker slot not reacquired after timeout")
	}
	close(events)
	if _, status := s.waitForEvent(events, time.Second); status != http.StatusBadRequest {
		t.Fatalf("cancelled subscription status=%d", status)
	}
}

func TestConcurrentPublishOrder(t *testing.T) {
	b := NewBroker()
	b.Publish("news", []byte("before subscription"))
	_, a := b.Subscribe("news")
	_, c := b.Subscribe("news")
	_, other := b.Subscribe("other")
	var wg sync.WaitGroup
	for i := 0; i < 4; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 20; j++ {
				b.Publish("news", []byte("message"))
			}
		}()
	}
	wg.Wait()
	for seq := uint64(1); seq <= 80; seq++ {
		for _, sub := range []*Subscriber{a, c} {
			select {
			case msg := <-sub.messages:
				if msg.Seq != seq || string(msg.Data) != "message" {
					t.Fatalf("got %+v; want seq=%d", msg, seq)
				}
			default:
				t.Fatalf("missing message seq=%d", seq)
			}
		}
	}
	if len(other.messages) != 0 {
		t.Fatal("message delivered to another topic")
	}
	for i := 0; i < SubscriptionBufferSize+10; i++ {
		b.Publish("news", nil)
	}
	if len(a.messages) != SubscriptionBufferSize {
		t.Fatal("queue is not bounded at the configured capacity")
	}
}
